class API:
    """API-layer actions."""

    @staticmethod
    def api_login(username, password):
        """Validates credentials."""
        if username == "":
            return {"ok": False, "error": "Username is required"}

        if password == "":
            return {"ok": False, "error": "Password is required"}

        user = Database.db_get_user(username)
        if user is None or user["password"] != password:
            return {"ok": False, "error": "Invalid username or password"}

        return {"ok": True, "user_id": user["id"], "display_name": user["display_name"]}

    @staticmethod
    def api_search_books(query):
        """Searches books case-insensitively."""
        all_books = Database.db_get_all_books()

        if query == "":
            return {"ok": True, "books": all_books}

        query_lower = query.lower()
        matching_books = []

        for book in all_books:
            # Partial match for title and author, exact match for ISBN
            if (query_lower in book["title"].lower() or 
                query_lower in book["author"].lower() or 
                query == book["isbn"]):
                matching_books.append(book)

        return {"ok": True, "books": matching_books}

    @staticmethod
    def api_get_book(book_id):
        """Returns details for specified book_id."""
        book = Database.db_get_book(book_id)
        if book is None:
            return {"ok": False, "error": "Book not found"}
        return {"ok": True, "book": book}

    @staticmethod
    def api_borrow_book(user_id, book_id):
        """Attempts to borrow book."""
        book = Database.db_get_book(book_id)
        if book is None:
            return {"ok": False, "error": "Book not found"}

        if book["available_copies"] == 0:
            return {"ok": False, "error": "No copies available"}

        if Database.db_user_has_borrowed_book(user_id, book_id):
            return {"ok": False, "error": "You have already borrowed this book"}

        if Database.db_count_user_active_borrowings(user_id) >= CONFIG["borrowing_limit"]:
            return {"ok": False, "error": "You have reached your borrowing limit"}

        # Create borrowing
        borrowing_id = DB._next_borrowing_id
        DB._next_borrowing_id += 1

        DB.borrowings[borrowing_id] = {
            "id": borrowing_id,
            "user_id": user_id,
            "book_id": book_id,
            "borrow_date": CONFIG["current_date"],
            "due_date": "2024-02-24",
            "status": "borrowed"
        }

        DB.books[book_id]["available_copies"] -= 1

        return {"ok": True, "borrowing_id": borrowing_id, "due_date": "2024-02-24"}

    @staticmethod
    def api_return_book(user_id, borrowing_id):
        """Returns borrowed book."""
        borrowing = Database.db_get_borrowing(borrowing_id)

        if borrowing is None or borrowing["user_id"] != user_id:
            return {"ok": False, "error": "Borrowing not found"}

        if borrowing["status"] == "returned":
            return {"ok": False, "error": "Book already returned"}

        DB.borrowings[borrowing_id]["status"] = "returned"
        DB.books[borrowing["book_id"]]["available_copies"] += 1

        return {"ok": True}

    @staticmethod
    def api_get_user_borrowings(user_id):
        """Returns all borrowings for user_id with status='borrowed'."""
        borrowings = []
        for borrowing in DB.borrowings.values():
            if borrowing["user_id"] == user_id and borrowing["status"] == "borrowed":
                book = Database.db_get_book(borrowing["book_id"])
                borrowings.append({
                    "borrowing_id": borrowing["id"],
                    "book_id": borrowing["book_id"],
                    "title": book["title"],
                    "author": book["author"],
                    "borrow_date": borrowing["borrow_date"],
                    "due_date": borrowing["due_date"],
                    "status": borrowing["status"]
                })
        return {"ok": True, "borrowings": borrowings}


class Database:
    """Direct DB-layer access, for verifying what was really stored."""

    @staticmethod
    def db_get_user(username):
        """Returns user record for given username, or None if not found."""
        for user in DB.users.values():
            if user["username"] == username:
                return dict(user)
        return None

    @staticmethod
    def db_get_book(book_id):
        """Returns book record for given book_id, or None if not found."""
        book = DB.books.get(book_id)
        return dict(book) if book else None

    @staticmethod
    def db_get_borrowing(borrowing_id):
        """Returns borrowing record for given borrowing_id, or None if not found."""
        borrowing = DB.borrowings.get(borrowing_id)
        return dict(borrowing) if borrowing else None

    @staticmethod
    def db_count_user_active_borrowings(user_id):
        """Counts and returns number of active (status='borrowed') borrowings for the user."""
        count = 0
        for borrowing in DB.borrowings.values():
            if borrowing["user_id"] == user_id and borrowing["status"] == "borrowed":
                count += 1
        return count

    @staticmethod
    def db_user_has_borrowed_book(user_id, book_id):
        """Returns true if user has a borrowing record with this book_id and status='borrowed', false otherwise."""
        for borrowing in DB.borrowings.values():
            if (borrowing["user_id"] == user_id and 
                borrowing["book_id"] == book_id and 
                borrowing["status"] == "borrowed"):
                return True
        return False

    @staticmethod
    def db_get_all_books():
        """Returns all book records in the database."""
        return [dict(book) for book in DB.books.values()]


