        static ReturnBookResult apiReturnBook(Integer userId, int borrowingId) {
            Borrowing borrowing = Database.dbGetBorrowing(borrowingId);

            if (borrowing == null || borrowing.userId != userId) {
                return new ReturnBookResult(false, "Borrowing not found");
            }

            if (borrowing.status.equals("returned")) {
                return new ReturnBookResult(false, "Book already returned");
            }

            BORROWINGS.get(borrowingId).status = "returned";
            BOOKS.get(borrowing.bookId).availableCopies++;

            return new ReturnBookResult(true, null);
        }

        static GetUserBorrowingsResult apiGetUserBorrowings(int userId) {
            List<BorrowedBook> borrowings = new ArrayList<>();
            for (Borrowing borrowing : BORROWINGS.values()) {
                if (borrowing.userId == userId && borrowing.status.equals("borrowed")) {
                    Book book = Database.dbGetBook(borrowing.bookId);
                    borrowings.add(new BorrowedBook(
                        borrowing.id,
                        borrowing.bookId,
                        book.title,
                        book.author,
                        borrowing.borrowDate,
                        borrowing.dueDate,
                        borrowing.status
                    ));
                }
            }
            return new GetUserBorrowingsResult(true, borrowings);
        }
    }

