    static class Database {
        static User dbGetUser(String username) {
            for (User user : USERS.values()) {
                if (user.username.equals(username)) {
                    return user.copy();
                }
            }
            return null;
        }

        static Book dbGetBook(int bookId) {
            Book book = BOOKS.get(bookId);
            return book == null ? null : book.copy();
        }

        static Borrowing dbGetBorrowing(int borrowingId) {
            Borrowing borrowing = BORROWINGS.get(borrowingId);
            return borrowing == null ? null : borrowing.copy();
        }

        static int dbCountUserActiveBorrowings(int userId) {
            int count = 0;
            for (Borrowing borrowing : BORROWINGS.values()) {
                if (borrowing.userId == userId && borrowing.status.equals("borrowed")) {
                    count++;
                }
            }
            return count;
        }

        static boolean dbUserHasBorrowedBook(int userId, int bookId) {
            for (Borrowing borrowing : BORROWINGS.values()) {
                if (borrowing.userId == userId &&
                    borrowing.bookId == bookId &&
                    borrowing.status.equals("borrowed")) {
                    return true;
                }
            }
            return false;
        }

        static List<Book> dbGetAllBooks() {
            List<Book> books = new ArrayList<>();
            for (Book book : BOOKS.values()) {
                books.add(book.copy());
            }
            return books;
        }
    }

